function A.ExampleText(entry) return (entry.text:gsub("%s+","")) end
function S:Examples()
    local out={};for i,e in ipairs(A.Examples) do out[i]={id=e.id,name=e.name,description=e.description} end;return out
end
-- Imports one example as a new, disabled graph and selects it.
function S:ImportExample(id)
    local entry;for _,e in ipairs(A.Examples) do if e.id==id then entry=e end end
    assert(entry,"Unknown example")
    local token=self:PreviewTransfer(A.ExampleText(entry))
    local imported=self:ImportTransfer(token,#token.conflicts>0 and "copy" or nil)
    self.message="Example imported: "..entry.name..". "..entry.description.." Review, Save, then enable the graph."
    self:Changed()
    return imported
end
